 const runImport=async(file:File)=>{setError('');setBusy(true);try{if(file.size>12_000_000)throw new Error('文件最大12MB');const data=await new Promise<string>((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(file)});await stream('/import',{...command(),mime:file.type,data,filename:file.name},(type,p)=>{if(type==='status')setStatus(p.text);if(type==='project'){setProject(p);setMode('2d');setSelected(p.candidate?.walls[0]?.id||'')}if(type==='error')setError(p.error)})}catch(e){setError((e as Error).message)}finally{setBusy(false);setStatus('')}};
 const send=async(input:ChatDraft={attachmentIds:chatAttachments.map(a=>a.id),text,reference,roomId:room||project!.scene?.rooms[0]?.id||null,model})=>{if((!input.recommendationId&&!input.text.trim()&&!input.reference&&!input.attachmentIds?.length)||busy||!input.model)return;const draft={...input,respondentId:input.respondentId??visionRespondentId,reference:input.reference?{...input.reference}:null};setBusy(true);setChatProgress('正在思考…');setError('');if(!draft.recommendationId){setText('');setReference(null)}let streamError='';try{await stream('/chat',{...command(),...(draft.respondentId?{respondentId:draft.respondentId}:{}),...(draft.recommendationId?{recommendationId:draft.recommendationId}:{}),attachmentIds:draft.attachmentIds||[],text:draft.text||(draft.recommendationId?'根据已确认回答生成家具候选':draft.attachmentIds?.length?'请实际识别本轮上传的户型附件，生成待校正候选。':'请帮我理解这张参考图片，并先与我确认偏好。'),roomId:draft.roomId,model:draft.model,...(draft.reference?{image:draft.reference}:{})},(type,data)=>{if(type==='project')setProject(data);if(type==='delta')setProject(p=>p?{...p,messages:p.messages.map(m=>m.id===data.id?{...m,text:m.text+data.text}:m)}:p);if(type==='error'){streamError=data.error;setError(data.error)}if(type==='status')setChatProgress(data.text);if(type==='ui_action')applyUiAction(data)});if(streamError){if(!draft.recommendationId){setText(draft.text);setReference(draft.reference)}setRetryDraft(draft)}else{setRetryDraft(null);if(!draft.recommendationId)setChatAttachments([])}}catch(e){setError((e as Error).message);if(!draft.recommendationId){setText(draft.text);setReference(draft.reference)}setRetryDraft(draft)}finally{setBusy(false);setChatProgress(null)}};
 const transcribe=async(blob:Blob)=>{setBusy(true);setTranscribing(true);setError('');setStatus('正在转成可编辑文字…');try{const wav=blob.type==='audio/wav'?blob:await toWav(blob);const data=await new Promise<string>((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(wav)});const result=await api('/transcribe',{data,format:'wav'});setText(old=>old?old+'\n'+result.text:result.text);setStatus('转写已放入输入框，请检查后发送；录音临时内容已清除。')}catch(e){setError((e as Error).message)}finally{setTranscribing(false);setBusy(false)}};
 const toggleRecording=async()=>{if(recording){recorder.current?.stop();return}try{const media=await navigator.mediaDevices.getUserMedia({audio:true});const r=new MediaRecorder(media);recorder.current=r;discardRecording.current=false;let parts:Blob[]=[];r.ondataavailable=e=>parts.push(e.data);r.onstop=()=>{media.getTracks().forEach(t=>t.stop());if(recordTimer.current)clearTimeout(recordTimer.current);setRecording(false);const discarded=discardRecording.current,blob=new Blob(parts,{type:r.mimeType});parts=[];recorder.current=null;discardRecording.current=false;if(discarded){setStatus('已取消录音，临时录音已清除。');return}void transcribe(blob)};r.start();setRecording(true);recordTimer.current=setTimeout(()=>{if(r.state==='recording')r.stop()},60000)}catch(e){setError('无法使用麦克风，请允许权限或上传WAV录音。')}};
