 <div className="canvas-wrap">{reviewLocation?.revision===project.revision&&<span className="style-preview-label" role="status">{reviewLocation.finding.path?'受阻路径与关联对象（非推荐路线）':'复核问题位置'} · {reviewLocation.finding.title}</span>}{stylePreview&&<span className="style-preview-label" role="status">房间样式预览 · 尚未采用</span>}{mode==='2d'?<Plan reviewFinding={reviewLocation?.revision===project.revision?reviewLocation.finding:undefined} roomStyles={visibleStyles} issues={diagnostics.report?.analysis.issues||[]} activeWarning={selectedWarning} zones={project.zones||[]} zoneDrawing={!candidate&&zoneDrawMode&&!readOnly&&!busy} onAddDivider={(a,b)=>void divideZone(a,b)} onAutoZone={!candidate&&!readOnly&&!busy?(point)=>void autoZone(point):undefined} wallDrawing={candidate&&drawWallMode&&!readOnly&&!busy} onAddWall={(a,b)=>void drawWall(a,b)} onMoveWall={candidate&&!readOnly?(wallId,end,point)=>void topology({kind:'move-wall-endpoint',wallId,end,point}).catch(()=>{}):undefined} onRenameRoom={candidate&&!readOnly?(roomId,name)=>void renameRoom(roomId,name).catch(()=>{}):undefined} onMoveRoomLabel={!readOnly?(roomId,position)=>void moveRoomLabel(roomId,position):undefined} roomLabelPositions={project.roomLabelPositions} onItemMove={!candidate&&!readOnly&&!busy?(id,x,y)=>void mutate('/commands',{changes:[{action:'update',targetId:id,values:{x,y}}],confirmed:true,reason:'二维拖动家具'}).catch(()=>{}):undefined} scene={scene} selected={selected} onSelect={setSelected} image={candidate?project.sourceImage:undefined}/>:building?<BuildingView roomStyles={visibleStyles} building={building} topology={scene} focusRoom={room} selected={selected} time={time} day={day} onSelect={setSelected} onFocusRoom={setRoom}/>:<SceneView roomStyles={visibleStyles} onMove={!candidate&&!readOnly&&!busy?(id,x,y)=>mutate('/commands',{changes:[{action:'update',targetId:id,values:{x,y}}],confirmed:true,reason:'三维拖动家具'}).then(()=>undefined):undefined} scene={scene} selected={selected} onSelect={setSelected} mode={mode} time={time} day={day} focusRoom={room}/>}{building&&<WalkthroughController active={mode==='walk'} scene={scene} focusRoom={room}/>}</div>
